html:
{%- 
    set is_rescheduled = doc.is_rescheduled == 1 or doc.entrance_test_status == "Rescheduled"
-%}

{%- if is_rescheduled -%}
    {%- set f_date = doc.re_allocation_date -%}
    {%- set f_test = doc.re_entrance_test_name or doc.re_entrance_test_list -%}
    {%- set f_seat_raw = doc.re_seat_number -%}
    {%- set f_seat = f_seat_raw.split('-')[-1] if f_seat_raw else '' -%}
    {%- set f_room = doc.re_room_name -%}
    {%- set f_code = doc.re_room_code -%}
    {%- set f_building = doc.re_building -%}
    {%- set f_floor = doc.re_floor -%}
    {%- set f_center = doc.re_center_name -%}
    {%- set f_address = doc.re_center_address -%}
    {%- set f_status = doc.re_allocation_status -%}
{%- else -%}
    {%- set f_date = doc.allocation_date -%}
    {%- set f_test = doc.entrance_test_name or doc.entrance_test_list -%}
    {%- set f_seat_raw = doc.seat_number -%}
    {%- set f_seat = f_seat_raw.split('-')[-1] if f_seat_raw else '' -%}
    {%- set f_room = doc.room_name -%}
    {%- set f_code = doc.room_code -%}
    {%- set f_building = doc.building -%}
    {%- set f_floor = doc.floor -%}
    {%- set f_center = doc.center_name -%}
    {%- set f_address = doc.center_address -%}
    {%- set f_status = doc.allocation_status -%}
{%- endif -%}

{%- set campus_display_name = frappe.db.get_value("Campus", doc.campus, "campus_name") if doc.campus else (doc.campus or "Institution of Legal Education") -%}
{%- set campus_logo_path = frappe.db.get_value("Campus", doc.campus, "logo") if doc.campus else None -%}
{%- set admit_no = doc.admit_card_number or ("AC-" + doc.name) -%}
{%- set dob = frappe.utils.formatdate(doc.date_of_birth) if doc.date_of_birth else "—" -%}
{%- set exam_date_time = (frappe.utils.format_datetime(f_date, "MMMM dd, yyyy; hh:mm a") if f_date else "—") -%}
{%- set centre_full = "<strong>" + (f_center or "—") + "</strong><br>" + (f_address or "—") -%}

{%- set _site = frappe.utils.get_url() -%}

{#- PRODUCTION IMAGE HANDLER -#}
{%- set _logo_src = '' -%}
{%- if campus_logo_path -%}
    {%- set _lb64 = get_file_b64(campus_logo_path) -%}
    {%- if _lb64 -%}
        {%- set _lext = (campus_logo_path.split('.')[-1] | lower) -%}
        {%- set _lmime = 'image/jpeg' if _lext in ['jpg','jpeg'] else ('image/png' if _lext == 'png' else 'image/svg+xml') -%}
        {%- set _logo_src = 'data:' ~ _lmime ~ ';base64,' ~ _lb64 -%}
    {%- else -%}{%- set _logo_src = _site ~ campus_logo_path -%}{%- endif -%}
{%- endif -%}

{%- set _photo_src = '' -%}
{%- if doc.profile -%}
    {%- set _pb64 = get_file_b64(doc.profile) -%}
    {%- if _pb64 -%}
        {%- set _pext = (doc.profile.split('.')[-1] | lower) -%}
        {%- set _pmime = 'image/jpeg' if _pext in ['jpg','jpeg'] else ('image/png' if _pext == 'png' else 'image/webp') -%}
        {%- set _photo_src = 'data:' ~ _pmime ~ ';base64,' ~ _pb64 -%}
    {%- else -%}{%- set _photo_src = _site ~ doc.profile -%}{%- endif -%}
{%- endif -%}

<!DOCTYPE html>
<html>
<head>
<link href="https://fonts.googleapis.com/css2?family=Times+New+Roman:ital,wght@0,400;0,700;1,400;1,700&display=swap" rel="stylesheet">
<meta charset="UTF-8"/>
<style>
    @page { size: A4; margin: 10mm; }
    html, body { margin: 0 !important; padding: 0 !important; background: #fff !important; }
    body { font-family: 'Times New Roman', Times, serif; font-size: 15px; color: #000;line-height: 1.2;}

    .card-page { width: 100%; border: 1.5px solid #000; background: #fff; page-break-after: always; overflow: hidden; margin-bottom: 0px;}
    .card-page:last-child { page-break-after: auto; }

    table { width: 100%; border-collapse: collapse; table-layout: fixed; }
    td { vertical-align: middle; padding: 0; }

    /* Header */
    .hdr-bg { background: #920C24 !important; color: #ffffff !important; border-bottom: 1.5px solid #000; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .univ-name { font-size: 18px; font-weight: bold; text-transform: uppercase; color: #ffffff !important; }
    .univ-sub { font-size: 12px; color: #ffffff !important; text-transform: uppercase; }

    /* Title */
    .title-strip { border-bottom: 1.5px solid #000; text-align: center; padding: 0px 0; background: #fff !important; }
    .t1 { font-size: 15px; font-weight: bold; margin-top: 4px; }
    .t2 { font-size: 14px; font-weight: bold; margin-top: 4px;margin-bottom: 8px; }

    /* Data Table */
    .main-body { padding: 0px; }
    .data-tbl { border-bottom: 1.5px solid #000; }
    .data-tbl td { padding: 6px 10px; border-bottom: 1px solid #000;  font-size: 13px; }
    .data-tbl td:last-child { border-right: none; }
    .data-tbl td.lb { font-weight: bold; width: 30%;padding:2px !important; }
    .data-tbl td.vl { width: 45%; color: #000;padding:2px !important; }

    .data-tbl tr:last-child td { border-bottom: none; }

    /* Photo */
    .photo-col { border-left: 1.5px solid #000; text-align: center; padding: 10px; vertical-align: middle; width: 25%; }
    .photo-box { width: 120px; height: 140px; border: 1px solid #000; background: #fff; margin: 0 auto; }

    /* Sig Section */
    .sig-area { padding-bottom: 18px;padding-top: 10px; text-align: center; font-size: 13px;}
    .sig-note { margin-bottom: 1px; }
    .sig-box-tbl { border: 1.5px solid #000; margin-top: 10px; }
    .sig-box-tbl td { border-right: 1.5px solid #000; width: 50%; height: 70px; vertical-align: top;}
    .sig-box-tbl td:last-child { border-right: none; }
    .sig-label { font-weight: bold; padding: 0px; text-align: center; border-bottom: 1px solid #000; display: block; }

    /* Instructions Section */
    .inst-padding { padding: 15px 25px; }
    .inst-header { font-size: 15px; font-weight: bold; text-align: center; margin-bottom: 5px; }
    .sec-head { font-size: 13px; font-weight: bold; color: #000; margin-top: 10px; margin-bottom: 6px; }

    .list-tbl td { padding: 0px !important; font-size: 13px; line-height: 1.2; vertical-align: top; }
    .list-tbl .mk { width: 25px; font-weight: normal;}
    .list-tbl .sub-mk { width: 30px; font-weight: normal; padding-left: 20px; gap:0;}
</style>
</head>
<body>

<!-- PAGE 1: ADMIT CARD -->
<div class="card-page">
    <table class="hdr-bg">
        <tr>
            <td style="width: 100px; padding: 10px;">
                <div style="background:#fff; width:70px; height:70px; border:1px solid #000; overflow:hidden; margin: 0 auto;">
                    {% if _logo_src %}<img src="{{ _logo_src }}" style="width:100%; height:100%; object-fit:contain;">
                    {% else %}<div style="color:#9b1c2e; font-weight:bold; text-align:center; line-height:70px; font-size:10px;">LOGO</div>{% endif %}
                </div>
            </td>
            <td style="text-align: center;">
                <div class="univ-name">{{ "National Law School of India University" or campus_display_name }}</div>
                <div class="univ-sub">BENGALURU</div>
            </td>
            <td style="width: 100px;"></td>
        </tr>
    </table>

    <div class="title-strip">
        <div class="t1">Admit Card ({{ f_test or "—" }})</div>
        <div class="t2">Admission to the {{ doc.program or "Programme" }} Programme</div>
    </div>

    <div class="main-body">
        <table class="data-tbl">
            <tr>
                <td class="lb">Admit Card Number</td><td class="vl">: {{ admit_no }}</td>
                <td rowspan="9" class="photo-col">
                    <div class="photo-box">
                        {% if _photo_src %}<img src="{{ _photo_src }}" style="width:100%; height:100%; object-fit:cover;">
                        {% else %}<div style="line-height:140px; font-size:40px; color:#ccc;">👤</div>{% endif %}
                    </div>
                </td>
            </tr>
            <tr><td class="lb">Candidate's Name</td><td class="vl">: {{ doc.candidate_name or "—" }}</td></tr>
            <tr><td class="lb">Date of Birth</td><td class="vl">: {{ dob }}</td></tr>
            <tr><td class="lb">Father's Name</td><td class="vl">: {{ doc.father_name or "—" }}</td></tr>
            <tr><td class="lb">Mother's Name</td><td class="vl">: {{ doc.mother_name or "—" }}</td></tr>
            <tr><td class="lb">Gender</td><td class="vl">: {{ doc.gender or "—" }}</td></tr>
            <tr><td class="lb">Examination Date & Time</td><td class="vl">: {{ exam_date_time|safe }}</td></tr>
            <tr><td class="lb">Reporting Time</td><td class="vl">: 09:15 am</td></tr>
        </table>
        <table>
            <tr class="data-tbl">
                <td class="lb">Test Centre Name &<br>Address</td>
                <td style="padding:2px !important">: {{ centre_full|safe }}</td>
            </tr>
        </table>
    </div>
</div>

<div class="sig-area">
    <div class="sig-note" style="margin:-6px !important;">To be signed in the presence of the Invigilator in the Examination Hall</div>
    <table class="sig-box-tbl">
        <tr>
            <td style="padding:0px !important;"><span class="sig-label">Candidate's Signature</span></td>
            <td style="padding:0px !important;"><span class="sig-label">Invigilator's Signature</span></td>
        </tr>
    </table>
</div>

<!-- PAGE 2: INSTRUCTIONS -->
<div class="card-page">
    <div class="inst-padding">
        <div class="inst-header">Instructions to Candidates</div>

        <div class="sec-head">1. General Instructions</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>Candidates should check and review their admit cards carefully and make sure that their Name, Date of Birth, and other personal details mentioned in the admit card are as per the details filled by them in the application form. In case of any discrepancy, please write to <b>nlsat.query@nls.ac.in</b>.</td></tr>
            <tr><td class="mk">b.</td><td>Please carry a printed copy of this admit card to the test centre.</td></tr>
            <tr><td class="mk">c.</td><td>Candidates shall be required to follow all directions issued by the Centre Superintendent and the Institution representatives at their respective test centres.</td></tr>
        </table>

        <div class="sec-head">2. Reporting to the Test Centre & Test Timings</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>The admissions test will commence at {{ (exam_date_time|safe).split(';')[0] if exam_date_time else "10:00 am" }}, and will be for a duration of 150 minutes (two hours and thirty minutes). Candidates will be allowed to enter the premises of the test centre from 9:15 am and should be seated in the examination hall by 9:30 am.</td></tr>
            <tr><td class="mk">b.</td><td>Candidates should carry a Government-issued photo ID card or a photo ID issued by a recognised educational institution. The ID card will be checked at the time of entry into the centre.</td></tr>
            <tr><td class="mk">c.</td><td>Candidates who arrive at the test centre beyond 10:15 am will not be permitted entry.</td></tr>
            <tr><td class="mk">d.</td><td>Once the test commences, Candidates will not be permitted to leave the examination hall until the test is completed, and all the Question Booklets and OMR response sheets have been collected by the invigilator/s.</td></tr>
        </table>

        <div class="sec-head">3. Permitted Items</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>Candidates will only be permitted to carry the following inside the Test Centre:</td></tr>
        </table>
        <table class="list-tbl">
            <tr><td class="sub-mk">i.</td><td>Admit Card (In case the photograph on the Admit Card is not clear, candidates should carry a self-attested passport size photograph).</td></tr>
            <tr><td class="sub-mk">ii.</td><td>Government Issued Photo ID or a photo ID issued by a recognised educational institution.</td></tr>
            <tr><td class="sub-mk">iii.</td><td>Black or Blue Ballpoint pen.</td></tr>
            <tr><td class="sub-mk">iv.</td><td>A transparent water bottle.</td></tr>
            <tr><td class="sub-mk">v.</td><td>An analogue watch. <strong>Note:</strong> Smart Watches are not permitted.</td></tr>
        </table>
    </div>
</div>
<div class="card-page">
    <div class="inst-padding">
        <div class="sec-head">4. Admissions Test Related Instructions</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>The {{ f_test or "Admissions Test" }} is for a maximum of 150 minutes and will be conducted in English. The paper will consist of two parts – Part A and Part B.</td></tr>
            <tr><td class="mk">b.</td><td>An attendance sheet will be circulated during the admissions test. The requisite details should be filled in the attendance sheet.</td></tr>
            <tr><td class="mk">c.</td><td>Candidates will be provided with a Question Booklet and an Optical Marker Reader (OMR) response sheet to answer the admissions test.</td></tr>
            <tr><td class="mk">d.</td><td>Candidates should use black/blue ball point pen <strong>only</strong> to enter the admit card number, and other required details in the Question Booklet and the OMR response sheet. Details should be filled in the Question Booklet and the OMR response sheet only after commencement of the test at 10 am. The packet containing the Question Booklet and the OMR response sheet should not be opened prior to 10 am.</td></tr>
            <tr><td class="mk">e.</td><td>Part A will consist of 75 multiple choice questions (MCQs) which will be answered on the OMR response sheet. Candidates must read the instructions provided with the Question Booklet and OMR sheet before commencing the test.</td></tr>
            <tr><td class="mk">f.</td><td>Use a black/blue ball point pen <strong>only</strong> for shading the circles/answer bubbles in the OMR response sheet. Indicate only one answer by shading one among the options provided. The answer bubble/circle should be shaded completely without leaving any gap/space. If a bubble/circle is shaded incompletely, the question will be considered unanswered. If more than one bubble/circle is shaded in response to a question, that question too will be considered unanswered. Candidates should not make any stray marks anywhere on the OMR sheet.</td></tr>
            <tr><td class="mk">g.</td><td>Responses to questions in Part B of the paper shall be written in the space provided in the Question Booklet. Candidates should write the details required on the cover page of the Question Booklet.</td></tr>
            <tr><td class="mk">h.</td><td>Candidates are allowed to underline parts of the passage or questions. However, making any other marking or writing notes directly on the question paper is prohibited. Separate space is provided for making notes and for rough work.</td></tr>
            <tr><td class="mk">i.</td><td>No clarifications can be sought about the Question Booklet from anyone.</td></tr>
            <tr><td class="mk">j.</td><td>The OMR response sheet has a carbon copy. Candidates should return the original OMR response sheet (the first sheet), and their Question Booklet (with their answers to Part B of the paper) to the invigilator/s at the end of the admissions test. Candidates are permitted to carry the carbon copy (second sheet) of the OMR response sheet with them. Candidates shall not carry the Question Booklet out of the examination hall under any circumstances.</td></tr>
        </table>

        <div class="sec-head">5. Marking Scheme</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>The {{ f_test or "Admissions Test" }} is for a total of 150 (One hundred and fifty) marks. Parts A and B are for 75 marks each. Every correct answer in Part A will be awarded one mark. Every wrong answer, and every unanswered question will lead to a deduction of 0.25 marks.</td></tr>
        </table>

        <div class="sec-head">6. Documents to be retained by the Candidate after the test</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>The admit card, with the invigilator's signature should be retained by the candidate and produced at the Institution at the time of admission.</td></tr>
        </table>

        <div class="sec-head">7. Malpractice</div>
        <table class="list-tbl">
            <tr><td class="mk">a.</td><td>The use of any unfair means by a Candidate shall result in their disqualification, and cancellation of their test.</td></tr>
            <tr><td class="mk">b.</td><td>Impersonation is an offence, and the Candidate, apart from being disqualified, shall be liable to penal action under the law.</td></tr>
            <tr><td class="mk">c.</td><td>Possession of electronic devices, including mobile phones, headphones, earphones, smart watches, calculators etc., is strictly prohibited in the examination hall.</td></tr>
        </table>
    </div>
</div>

</body>
</html>
